<script setup lang="ts">
import { ArrowDownRight, ArrowRight, ArrowUpRight, CalendarDays, ChevronDown, CircleAlert, Coins, FileCheck2, FileText, RefreshCw, Users, Clock3 } from '@lucide/vue'

definePageMeta({ middleware: 'auth', ssr: false })

interface Metric { key: string; label: string; value: number; format: 'number' | 'currency' | 'percent' | 'days'; change: number | null; previousValue: number | null }
interface TrendPoint { label: string; registered: number; signed: number; commercial: number; verification: number; verified: number; appointments: number }
interface Breakdown { key: string; label: string; value: number }
interface WorkItem { id: string; contractId: string; contractNumber: string; holderName: string; holderDni: string; program: string; advisorName: string; status: string; location: string; updatedAt: string; queueEnteredAt: string | null; appointmentAt: string | null; appointmentType: string | null; observation: string | null; queueReason?: string | null; documentCount: number; missingDocuments: string[] }
interface Advisor { id: string; name: string; total: number; signed: number; cancelled: number; contracted: number; signingRate: number }
interface DashboardData { role: string; scope: string; period: number; summary: Record<string, number>; metrics: Metric[]; trend: TrendPoint[]; contractStatusBreakdown: Breakdown[]; expedientStatusBreakdown: Breakdown[]; locationBreakdown: Array<{ location: string; status: string; value: number }>; priorities: Array<{ key: string; label: string; value: number; href: string }>; advisors: Advisor[]; workQueue: WorkItem[] }

const { user, verifyToken } = useAuth()
const data = ref<DashboardData | null>(null)
const loading = ref(true)
const error = ref('')
const period = ref(30)
const queueStatus = ref('')
const nf = new Intl.NumberFormat('es-PE')
const money = (value: number) => new Intl.NumberFormat('es-PE', { style: 'currency', currency: 'PEN', maximumFractionDigits: 0 }).format(value || 0)
const formatValue = (metric: Metric, value = metric.value) => metric.format === 'currency' ? money(value) : metric.format === 'percent' ? `${nf.format(value)}%` : metric.format === 'days' ? `${nf.format(value)} d` : nf.format(value)
const firstName = computed(() => user.value?.name?.split(' ')[0] || 'bienvenido')
const statusLabels: Record<string, string> = { REVISION: 'En revisión', FIRMADO: 'Firmado', ANULADO: 'Anulado', CREADO: 'Por revisar', REBOTADO: 'Rebotado', AGENDADO: 'Cita programada', OBSERVADO: 'Con observaciones', VERIFICADO: 'Verificado', ANULACION_PENDIENTE: 'Firma pendiente' }
const statusTone: Record<string, string> = { REVISION: 'pending', FIRMADO: 'signed', ANULADO: 'neutral', CREADO: 'review', REBOTADO: 'danger', AGENDADO: 'review', OBSERVADO: 'pending', VERIFICADO: 'signed', ANULACION_PENDIENTE: 'pending' }
const fmtStatus = (key: string) => statusLabels[key] || key.replaceAll('_', ' ')
const metricIcons = [Users, FileText, Clock3, Coins]
const chartSeries = computed(() => ['asistente_comercial', 'verificador'].includes(data.value?.role || '') ? [{ key: 'commercial', label: 'Recibidos', color: '#1769e0' }, { key: 'verification', label: 'Derivados', color: '#d71943' }] : [{ key: 'registered', label: 'Matrículas', color: '#1769e0' }, { key: 'signed', label: 'Contratos firmados', color: '#d71943' }])
const chartPoints = computed(() => {
  const points = data.value?.trend || []
  const max = Math.max(...points.flatMap((point) => chartSeries.value.map((series) => Number(point[series.key as keyof TrendPoint]) || 0)), 1)
  return points.map((point, index) => ({ ...point, x: points.length > 1 ? 34 + index * (650 / (points.length - 1)) : 34, values: chartSeries.value.map((series) => ({ ...series, value: Number(point[series.key as keyof TrendPoint]) || 0, y: 204 - ((Number(point[series.key as keyof TrendPoint]) || 0) / max) * 165 })) }))
})
const linePath = (seriesIndex: number) => chartPoints.value.map((point, index) => `${index ? 'L' : 'M'} ${point.x} ${point.values[seriesIndex]?.y ?? 204}`).join(' ')
const areaPath = (seriesIndex: number) => `${linePath(seriesIndex)} L ${chartPoints.value.at(-1)?.x || 684} 204 L ${chartPoints.value[0]?.x || 34} 204 Z`
const chartMax = computed(() => Math.max(...(data.value?.trend || []).flatMap((point) => chartSeries.value.map((series) => Number(point[series.key as keyof TrendPoint]) || 0)), 1))
const doughnutTotal = computed(() => (data.value?.contractStatusBreakdown || []).reduce((total, segment) => total + segment.value, 0))
const doughnutStyle = computed(() => { let cursor = 0; const colors = ['#d71943', '#9fb2d0', '#6da5f0', '#c9d6ea']; return (data.value?.contractStatusBreakdown || []).map((segment, index) => { const start = cursor; cursor += doughnutTotal.value ? segment.value / doughnutTotal.value * 100 : 0; return `${colors[index % colors.length]} ${start}% ${cursor}%` }).join(', ') || '#e5eaf2 0 100%' })
const stageGroups = computed(() => { const locations = [{ key: 'ASESOR', label: 'Admisión' }, { key: 'ASISTENTE_COMERCIAL', label: 'Finanzas' }, { key: 'SUPERVISOR', label: 'Legal' }, { key: 'VERIFICACION', label: 'Firma de contrato' }]; return locations.map((location) => ({ ...location, value: (data.value?.locationBreakdown || []).filter((row) => row.location === location.key && row.status !== 'VERIFICADO').reduce((sum, row) => sum + row.value, 0) })).filter((stage) => stage.value > 0) })
const maxStage = computed(() => Math.max(...stageGroups.value.map((stage) => stage.value), 1))
const filteredQueue = computed(() => (data.value?.workQueue || []).filter((item) => !queueStatus.value || item.status === queueStatus.value).slice(0, 5))
const queueStatuses = computed(() => [...new Set((data.value?.workQueue || []).map((item) => item.status))])
const changeIsGood = (metric: Metric) => ['pendingSignatures', 'commercialReturned', 'overdueAppointments'].includes(metric.key) ? (metric.change || 0) <= 0 : (metric.change || 0) >= 0
const ageDays = (item: WorkItem) => Math.max(0, Math.floor((Date.now() - new Date(item.queueEnteredAt || item.updatedAt).getTime()) / 86400000))
const loadDashboard = async () => { loading.value = true; error.value = ''; try { data.value = await $fetch<DashboardData>('/api/dashboard', { credentials: 'include', query: { period: period.value } }) } catch (err: any) { error.value = err?.data?.statusMessage || 'No pudimos cargar el dashboard.' } finally { loading.value = false } }
onMounted(async () => { if (!user.value) await verifyToken(); await loadDashboard() })
</script>

<template>
  <div class="dashboard-page">
    <AppHeader title="Dashboard" subtitle="Centro de operaciones de matrículas" />
    <main class="dashboard-content">
      <section class="dashboard-intro">
        <div><h1>Hola, {{ firstName }}</h1><p>Aquí tienes el resumen de la operación de matrículas y contratos.</p></div>
        <div class="period-control"><span>Periodo</span><label for="dashboard-period" class="sr-only">Periodo</label><select id="dashboard-period" v-model="period" @change="loadDashboard"><option :value="7">Últimos 7 días</option><option :value="30">Últimos 30 días</option><option :value="90">Últimos 90 días</option><option :value="365">Último año</option></select><CalendarDays class="period-icon" /><ChevronDown class="period-chevron" /></div>
      </section>

      <div v-if="error" class="dashboard-error" role="alert"><span>{{ error }}</span><button type="button" @click="loadDashboard"><RefreshCw :size="15" /> Reintentar</button></div>
      <div v-if="loading" class="dashboard-loading"><UiSkeleton v-for="item in 8" :key="item" class="rounded-lg" :class="item < 5 ? 'h-28' : 'h-64'" /></div>
      <template v-else-if="data">
        <section class="metric-grid" aria-label="Indicadores principales">
          <article v-for="(metric, index) in data.metrics.slice(0, 4)" :key="metric.key" class="metric-card"><span class="metric-icon" :class="`metric-icon-${index}`"><component :is="metricIcons[index] || FileText" :size="27" /></span><div class="metric-copy"><p>{{ metric.label }}</p><div class="metric-value-row"><strong>{{ formatValue(metric) }}</strong><span v-if="metric.change !== null" :class="changeIsGood(metric) ? 'change-good' : 'change-bad'"><ArrowUpRight v-if="metric.change >= 0" :size="14" /><ArrowDownRight v-else :size="14" /> {{ metric.change > 0 ? '+' : '' }}{{ metric.change }}%</span></div><small>{{ metric.previousValue !== null ? `vs. periodo anterior (${formatValue(metric, metric.previousValue)})` : 'Casos actuales que requieren seguimiento' }}</small></div></article>
        </section>

        <section class="dashboard-middle">
          <article class="panel trend-panel"><div class="panel-heading"><div><h2>Evolución de matrículas y firmas</h2><p>Comparativo mensual del número de matrículas vs. contratos firmados.</p></div><select aria-label="Agrupación de la gráfica"><option>Mensual</option><option>Semanal</option></select></div><div class="chart-wrap"><div class="chart-y-labels"><span>{{ chartMax }}</span><span>{{ Math.round(chartMax * .75) }}</span><span>{{ Math.round(chartMax * .5) }}</span><span>{{ Math.round(chartMax * .25) }}</span><span>0</span></div><svg class="trend-chart" viewBox="0 0 720 250" role="img" aria-label="Evolución de matrículas y firmas"><defs><linearGradient id="blueArea" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#1769e0" stop-opacity=".12" /><stop offset="1" stop-color="#1769e0" stop-opacity="0" /></linearGradient></defs><g class="chart-grid"><line v-for="y in [39,80,121,162,204]" :key="y" x1="34" :y1="y" x2="684" :y2="y" /><line v-for="x in chartPoints" :key="x.x" :x1="x.x" y1="39" :x2="x.x" y2="204" /></g><path v-if="chartPoints.length" :d="areaPath(0)" fill="url(#blueArea)" /><path v-for="(series, index) in chartSeries" :key="series.key" :d="linePath(index)" fill="none" :stroke="series.color" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" /><template v-for="point in chartPoints" :key="point.x"><circle v-for="series in point.values" :key="series.key" :cx="point.x" :cy="series.y" r="3.5" :fill="series.color" stroke="white" stroke-width="2" /></template></svg><div class="chart-x-labels"><span v-for="point in chartPoints" :key="point.x">{{ point.label }}</span></div></div><div class="chart-legend"><span v-for="series in chartSeries" :key="series.key"><i :style="{ background: series.color }" />{{ series.label }}</span></div></article>

          <article class="panel status-panel"><div class="panel-heading"><div><h2>Estado de contratos</h2><p>Distribución por estado actual.</p></div></div><div class="donut-wrap"><div class="donut" :style="{ background: `conic-gradient(${doughnutStyle})` }"><div><strong>{{ nf.format(doughnutTotal) }}</strong><span>contratos<br />totales</span></div></div></div><div class="status-list"><div v-for="(segment, index) in data.contractStatusBreakdown" :key="segment.key"><span><i class="status-dot" :class="`dot-${index}`" />{{ fmtStatus(segment.key) }}</span><b>{{ nf.format(segment.value) }}</b><small>{{ doughnutTotal ? Math.round(segment.value / doughnutTotal * 100) : 0 }}%</small></div></div></article>

          <div class="side-panels"><article class="panel stages-panel"><div class="panel-heading"><div><h2>Expedientes por etapa responsable</h2><p>Número de expedientes en cada etapa del proceso.</p></div></div><div class="stage-list"><div v-for="stage in stageGroups" :key="stage.key"><span>{{ stage.label }}</span><div><i :style="{ width: `${Math.max(stage.value / maxStage * 100, 3)}%` }" /></div><b>{{ nf.format(stage.value) }}</b></div><p v-if="!stageGroups.length" class="empty-copy">Sin expedientes registrados.</p></div></article><article class="panel advisors-panel"><div class="panel-heading"><div><h2>Rendimiento de asesores</h2><p>Matrículas, firmas, tasa de conversión y valor contratado.</p></div><NuxtLink to="/matriculas">Ver todos <ArrowRight :size="14" /></NuxtLink></div><div class="advisor-table"><div class="advisor-row advisor-head"><span>Asesor</span><span>Matrículas</span><span>Firmas</span><span>Conversión</span><span>Valor contratado</span></div><div v-for="advisor in [...data.advisors].sort((a, b) => b.signed - a.signed).slice(0, 5)" :key="advisor.id" class="advisor-row"><span class="advisor-name"><i>{{ advisor.name.split(' ').map((name) => name[0]).slice(0, 2).join('') }}</i>{{ advisor.name }}</span><span>{{ advisor.total }}</span><span>{{ advisor.signed }}</span><span>{{ advisor.signingRate }}%</span><span>{{ money(advisor.contracted) }}</span></div><p v-if="!data.advisors.length" class="empty-copy">No hay asesores para comparar.</p></div></article></div>
        </section>

        <section class="panel queue-panel"><div class="queue-heading"><div><h2>Cola de trabajo</h2><p>Matrículas con contrato pendiente o en proceso, ordenadas por mayor tiempo de espera.</p></div><div class="queue-actions"><select v-model="queueStatus" aria-label="Filtrar cola por estado"><option value="">Todos los estados</option><option v-for="status in queueStatuses" :key="status" :value="status">{{ fmtStatus(status) }}</option></select><NuxtLink to="/matriculas">Ver cola completa <ArrowRight :size="15" /></NuxtLink></div></div><div class="queue-scroll"><table><thead><tr><th>Estudiante / titular</th><th>DNI</th><th>Programa</th><th>Asesor asignado</th><th>Estado actual</th><th>Días en espera</th><th>Última actividad</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in filteredQueue" :key="item.id"><td><strong>{{ item.holderName }}</strong></td><td>{{ item.holderDni }}</td><td>{{ item.program }}</td><td>{{ item.advisorName }}</td><td><span class="status-pill" :class="statusTone[item.status] || 'neutral'">{{ fmtStatus(item.status) }}</span></td><td>{{ ageDays(item) }}</td><td>{{ new Date(item.updatedAt).toLocaleDateString('es-PE', { day: '2-digit', month: 'short', year: 'numeric' }) }}</td><td><NuxtLink :to="item.location === 'ASESOR' ? `/matricula/${item.contractId}` : `/expedientes/${item.id}`">Ver detalle <ArrowRight :size="14" /></NuxtLink></td></tr></tbody></table><div v-if="!filteredQueue.length" class="queue-empty"><CircleAlert :size="18" /> No hay casos pendientes para mostrar.</div></div></section>
      </template>
      <div v-else-if="!error" class="empty-state"><p>No hay información para mostrar</p><button type="button" @click="loadDashboard">Recargar</button></div>
    </main>
  </div>
</template>

<style scoped>
