.dashboard-intro h1 { margin: 0; color: #071a4d; font-size: 27px; line-height: 1.1; letter-spacing: -.04em; }
.dashboard-intro p, .panel-heading p, .queue-heading p { margin: 5px 0 0; color: #657695; font-size: 13px; }
