.period-icon { position: absolute; right: 95px; width: 15px; color: #53688e; pointer-events: none; }.period-chevron { position: absolute; right: 9px; width: 14px; pointer-events: none; }
.dashboard-error { display: flex; justify-content: space-between; align-items: center; border: 1px solid #f3c4cb; border-radius: 7px; padding: 12px 15px; margin-bottom: 16px; background: #fff4f5; color: #8b152c; font-size: 13px; }.dashboard-error button, .empty-state button { display: inline-flex; align-items: center; gap: 6px; border: 1px solid #c8102e; border-radius: 5px; padding: 7px 11px; color: #c8102e; background: white; font-size: 12px; cursor: pointer; }
.dashboard-loading { display: grid; grid-template-columns: repeat(4, 1fr); gap: 13px; }.dashboard-loading > :nth-child(n+5) { grid-column: span 2; }
