isplay: grid; grid-template-columns: minmax(0, 1fr) 40px 30px; align-items: center; gap: 5px; padding: 4px 0; color: #25385f; font-size: 12px; }.status-list span { display: flex; align-items: center; gap: 8px; }.status-list b { text-align: right; font-weight: 600; }.status-list small { text-align: right; color: #53688e; }.status-dot { width: 10px; height: 10px; border-radius: 50%; }.dot-0 { background: #d71943; }.dot-1 { background: #9fb2d0; }.dot-2 { background: #6da5f0; }.dot-3 { background: #c9d6ea; }
.side-panels { display: grid; gap: 13px; min-width: 0; }.stages-panel { min-height: 185px; }.stage-list { padding: 8px 16px 16px; }.stage-list > div { display: grid; grid-template-columns: 100px minmax(0, 1fr) 30px; align-items: center; gap: 9px; margin: 12px 0; color: #273b61; font-size: 12px; }.stage-list > div > div { height: 15px; overflow: hidden; border-radius: 3px; background: #f0f3f8; }.stage-list i { display: block; height: 100%; border-radius: 3px; background: #2878df; }.stage-list b { text-align: right; color: #162d5c; font-size: 12px; }.empty-copy { margin: 10px 0; color: #8390a5; font-size: 12px; }.advisors-panel { min-height: 239px; }.advisor-table { overflow-x: auto; padding-bottom: 5px; }.advisor-row { display: grid; grid-template-columns: minmax(125px, 1.45fr) .55fr .55fr .7fr 1.1fr; min-width: 430px; align-items: center; border-top: 1px solid #edf0f5; padding: 7px 15px; color: #283b61; font-size: 11px; }.advisor-head { border-top: 1px solid #e7ebf2; background: #f5f7fa; color: #506382; font-size: 10px; font-weight: 600; }.advisor-row > span:not(:first-child) { text-align: right; }.advisor-name { display: flex; align-items: center; gap: 7px; white-space: nowrap; }.advisor-name i { display: grid; place-items: center; width: 23px; height: 23px; border-radius: 50%; background: #f6c86c; color: #68430f; font-style: normal; font-size: 9px; font-weight: 700; }.advisor-row:nth-child(3n) .advisor-name i { background: #a8c8f5; color: #1d508f; }.advisor-row:nth-child(4n) .advisor-name i { background: #f2a5b8; color: #8b1b3d; }
.queue-panel { margin-top: 13px; }.queue-heading { align-items: center; padding: 15px 17px 13px; }.queue-actions { display: flex; align-items: center; gap: 18px; }.queue-actions select { min-width: 160px; padding: 0 11px; }.queue-scroll { overflow-x: auto; padding: 0 16px 10px; }.queue-scroll table { width: 100%; min-width: 990px; border-collapse: collapse; font-size: 11px; }.queue-scroll th { padding: 8px 12px; background: #f0f3f8; color: #22365d; text-align: left; font-size: 10px; font-weight: 700; white-space: nowrap; }.queue-scroll td { border-bottom: 1px solid #e6eaf1; padding: 8px 12px; color: #25385f; white-space: nowrap; }.queue-scroll td strong { color: #152d5b; font-weight: 600; }.queue-scroll td:last-child a { color: #0757ce; }.status-pill { display: inline-flex; border-radius: 999px; padding: 4px 9px; font-size: 10px; font-weight: 600; }.status-pill.signed { background: #dff6ed; color: #147550; }.status-pill.pending { background: #fff0c9; color: #8d5e06; }.status-pill.review { background: #dceaff; color: #1e5bb2; }.status-pill.danger { background: #ffe0e6; color: #a91736; }.status-pill.neutral { background: #edf0f5; color: #53617a; }.queue-empty { display: flex; justify-content: center; align-items: center; gap: 7px; padding: 32px; color: #75839b; font-size: 12px; }.empty-state { padding: 50px; text-align: center; color: #657695; }.empty-state button { margin-top: 12px; }
